import React, { useState } from 'react';
import { Outlet } from 'react-router-dom';
import Sidebar from './Sidebar';
import TopHeader from './TopHeader';
import { useApp } from '../../lib/AppContext';

export default function AdminLayout() {
  const [menuOpen, setMenuOpen] = useState(false);
  const { notify } = useApp();
  return <div className="app-shell"><Sidebar open={menuOpen} onClose={() => setMenuOpen(false)}/><main className="main"><TopHeader onMenu={() => setMenuOpen(true)} notify={notify}/><div className="content"><Outlet/></div><footer><span>© 2025 CEGCT · Community Environmental Guardian & Cleanliness Tracker</span><span><i/> All systems operational</span></footer></main></div>;
}
